const e = $input.first().json;
const miss = ['envelope_version','business_id','lead_id','trace_id'].filter(k => !e[k]);
if (miss.length) throw new Error('LEAD:' + (e.lead_id || '') + '|TRACE:' + (e.trace_id || '') + '|invalid envelope, missing: ' + miss.join(', '));
return [{ json: e }];

const L = $input.first().json;
if (!L.lead_id) return []; // not QUALIFIED: no-op
const cands = L.candidates || [];
const setup_incomplete = Number(L.catalog_size || 0) === 0; // no catalog at all = setup gate, not a product-fit problem
let no_reason = null;
if (!cands.length) {
  const budget = L.budget_value != null ? Number(L.budget_value) : null;
  if (budget != null && L.min_price != null && budget < Number(L.min_price)) no_reason = 'stated budget (' + budget + ') is below the cheapest in-stock item (' + L.min_price + ')';
  else no_reason = 'no in-stock catalog item matches the requested interest: ' + JSON.stringify(L.product_interest);
}
return [{ json: { lead_id: L.lead_id, business_id: L.business_id, trace_id: L.trace_id,
  contact_name: L.contact_name, company: L.company, budget_value: L.budget_value,
  budget_currency: L.budget_currency, product_interest: L.product_interest, urgency: L.urgency,
  band: L.band, candidates: cands, has_candidates: cands.length > 0, setup_incomplete, no_reason } }];

const raw = $input.first().json;
let r = raw;
if (r && Array.isArray(r.candidates)) r = { content: (r.candidates[0] || {}).content };
if (r && r.content && Array.isArray(r.content.parts)) r = r.content.parts.map(p => p.text || '').join('');
else if (r.content !== undefined) r = r.content;
if (typeof r === 'string') { try { r = JSON.parse(r.replace(/^```json?\s*|```\s*$/g, '')); } catch (e) { r = null; } }
const q = $('Prep Candidates').first().json;
const allowed = new Set((q.candidates || []).map(c => c.sku));
let items = (r && Array.isArray(r.items)) ? r.items.filter(i => i && allowed.has(i.sku)).slice(0, 3) : [];
return [{ json: { lead_id: q.lead_id, business_id: q.business_id, trace_id: q.trace_id,
  items, item_count: items.length } }];

const j = $input.first().json;
const src = $('Validate Envelope').first().json;
return [{ json: { envelope_version: '1.0', business_id: src.business_id, lead_id: j.lead_id, trace_id: src.trace_id, agent: 'recommender', status: 'ok', payload: {} } }];

const j = $input.first().json;
let out;
if (Array.isArray(j.candidates)) {
  out = { ...j, __model: 'gemini-2.5-flash', __fallback: false };
} else if (Array.isArray(j.choices)) {
  const u = j.usage || {};
  out = { candidates: [{ content: { parts: [{ text: (j.choices[0] && j.choices[0].message && j.choices[0].message.content) || '' }] },
    finishReason: (j.choices[0] && j.choices[0].finish_reason) || null }],
    usageMetadata: { promptTokenCount: u.prompt_tokens || 0, candidatesTokenCount: u.completion_tokens || 0, thoughtsTokenCount: 0 },
    __model: 'gpt-4o-mini', __fallback: true };
} else {
  out = { candidates: [], usageMetadata: {}, __model: 'unknown', __fallback: true };
}
return [{ json: out }];
